        if invite.status != "PENDING":
            return render(request, "users/invite_invalid.html")
        if invite.expires_at < timezone.now():
            invite.status = "EXPIRED"
            invite.save()
            return render(request, "users/invite_expired.html")

        # Store invite code in session
        request.session["family_invite_code"] = invite_code

        # Check if user with this email exists
        existing_user = User.objects.filter(email=invite.email).exists()

        context = {
            "invite": invite,
            "family": invite.family,
            "has_account": existing_user,
        }

        if request.user.is_authenticated:
            # Handle logged-in user
            if request.user.email.lower() != invite.email.lower():
                return render(request, "users/invite_wrong_email.html", context)
            # Redirect to acceptance handler
            return redirect("accept_family_invite_confirm", invite_code=invite_code)

        # Show public landing page
        return render(request, "users/invite_landing.html", context)

    except FamilyInvite.DoesNotExist:
        return render(request, "users/invite_not_found.html")


