def _sanitize_email_subject_value(value: str) -> str:
    """Prevent header injection by stripping newline characters."""
    return value.replace("\r", "").replace("\n", " ").strip()


def _check_network_invite_policy(target_family: FamilyGroup | None) -> tuple[bool, str]:
    """
    Check if the target family's network invite policy allows receiving invites.

    Returns:
        (is_allowed, error_message): tuple with permission result and optional error
    """
    if not target_family:
        # No target family pre-selected, allow the invite to proceed
        return True, ""

    policy = target_family.network_invite_policy
    if policy == FamilyGroup.NetworkInvitePolicy.DISABLED:
        return False, "Unable to send invite to this family."

    # NOTE: ALLOW and ADMIN_APPROVAL currently behave identically (both create
    # pending invites requiring acceptance). ADMIN_APPROVAL is reserved for future
    # functionality where family admins must explicitly approve incoming invites
    # before the invitation link is even sent.
    return True, ""


@login_required
def invite_member(request: HttpRequest) -> HttpResponse:
    """
    Invite a member to a family
    """
    if request.method != "POST":
        return redirect("family_management")

    user = cast(User, request.user)  # login_required guarantees User
    family_id = request.POST.get("family_id")
    email = (request.POST.get("email") or "").strip()
    role = request.POST.get("role")
    # invitation_type is used for UI clarity, helps identify the source modal
    # invitation_type = request.POST.get("invitation_type", "immediate")

    # Network creation fields
    network_action = request.POST.get("network_action", "")  # 'create' or 'existing'
    create_meta_group_flag = request.POST.get("create_meta_group")
    existing_meta_group_id = request.POST.get("existing_meta_group")
    meta_group_name = request.POST.get("meta_group_name")
    relationship_type = request.POST.get("relationship_type")
    relationship_context = request.POST.get(
        "relationship_context"
    )  # For META family invites
    invitation_message = request.POST.get("invitation_message", "")

    if relationship_type and relationship_type not in _VALID_RELATIONSHIP_TYPES:
        messages.error(request, "Invalid relationship type provided.")
        if family_id:
            return redirect("family_settings", family_id=family_id)
        return redirect("family_management")

    if (
        relationship_context
        and relationship_context not in _VALID_RELATIONSHIP_CONTEXTS
    ):
        messages.error(request, "Invalid relationship context provided.")
        if family_id:
            return redirect("family_settings", family_id=family_id)
        return redirect("family_management")

    # Normalize and validate network action inputs
    if network_action == "create":
