            "Choose either creating a new network or joining an existing one, not both.",
        )
        return redirect("family_settings", family_id=family_id)

    # Validate required fields for network creation
    if create_meta_group and not meta_group_name:
        messages.error(
            request, "Please provide a network name to create a new family network."
        )
        return redirect("family_settings", family_id=family_id)

    # Check if this is a META family inviting to their network
    try:
        if not family_id:
            raise FamilyGroup.DoesNotExist()
        inviting_family = FamilyGroup.objects.get(id=family_id)
        inviting_family_type = FamilyGroupType.objects.filter(
            family=inviting_family
        ).first()
        is_meta_family_invitation = (
            inviting_family_type and inviting_family_type.type == "META"
        )
    except (FamilyGroup.DoesNotExist, AttributeError):
        is_meta_family_invitation = False

    # For network invitations, role is not required (will use sender's role)
    if create_meta_group or existing_meta_group_id or is_meta_family_invitation:
        if not (family_id and email):
            messages.error(request, "Email address is required.")
            if family_id:
                return redirect("family_settings", family_id=family_id)
            return redirect("family_management")
        # Set role to the inviter's role for network invitations
        if not role:
            membership = FamilyMembership.objects.filter(
                user=user, family__id=family_id
            ).first()
            role = membership.role if membership else "OTHER"
    else:
        # For immediate family invitations, all fields are required
        if not (family_id and email and role):
            messages.error(request, "All fields are required.")
            if family_id:
                return redirect("family_settings", family_id=family_id)
            return redirect("family_management")

    # Validate email format
    from django.core.exceptions import ValidationError
    from django.core.validators import validate_email

    try:
        validate_email(email)
    except ValidationError:
        messages.error(request, "Please enter a valid email address.")
        if family_id:
            return redirect("family_settings", family_id=family_id)
        return redirect("family_management")

    email = email.lower()

    # Prevent self-invitation
    if email.lower() == user.email.lower():
        messages.error(request, "You cannot send an invitation to yourself.")
        if family_id:
            return redirect("family_settings", family_id=family_id)
        return redirect("family_management")

    try:
        # Get the family and verify the user is an admin
        family = FamilyGroup.objects.get(id=family_id)
        has_permission, error_msg = validate_family_admin_permission(
            user, family, "invite members"
        )

        if not has_permission:
            messages.error(request, error_msg or "Permission denied")
            return redirect("family_settings", family_id=family.id)

        # Determine the invitation context based on the parameters
        existing_meta_group_obj = None
        if existing_meta_group_id:
            try:
                existing_meta_group_obj = FamilyGroup.objects.get(
                    id=existing_meta_group_id
                )
            except FamilyGroup.DoesNotExist:
                pass

        invitation_context = determine_invitation_context(
            family,
            create_meta_group=create_meta_group,
            existing_meta_group=existing_meta_group_obj,
        )

        existing_user = User.objects.filter(email=email).first()

        if invitation_context in {"META_CREATE", "META_JOIN"}:
            # Handle network invitations via PendingMetaFamilyMembership
            family_type = FamilyGroupType.objects.filter(family=family).first()

            meta_family = existing_meta_group_obj
            if not meta_family and family_type and family_type.type == "META":
                meta_family = family

            # Avoid duplicate pending invites for the same admin/network pair
            duplicate_query = PendingMetaFamilyMembership.objects.filter(
                invited_email__iexact=email,
                source_family=family,
                invitation_context=invitation_context,
                status="PENDING",
            )
            if meta_family:
                duplicate_query = duplicate_query.filter(meta_family=meta_family)

            if duplicate_query.exists():
                messages.warning(
                    request,
                    f"There is already a pending network invite for {email}.",
                )
                return redirect("family_settings", family_id=family.id)

            # Attempt to pre-select the invited family when we can identify it
            target_family = None
            if existing_user:
                admin_families = FamilyGroup.objects.filter(
                    memberships__user=existing_user, memberships__is_admin=True
                )
                if meta_family:
                    admin_families = admin_families.exclude(id=meta_family.id)
                admin_families = admin_families.exclude(group_type__type="META")

                primary_family = getattr(existing_user.profile, "primary_family", None)
                if (
                    primary_family
                    and admin_families.filter(id=primary_family.id).exists()
                ):
                    target_family = primary_family
                elif admin_families.count() == 1:
                    target_family = admin_families.first()

                # If we couldn't pre-select a target family, verify the user has
                # at least one eligible family (non-DISABLED policy) before
                # creating the invite to avoid wasting invites
                if target_family is None and admin_families.exists():
                    eligible_families = admin_families.exclude(
                        network_invite_policy=FamilyGroup.NetworkInvitePolicy.DISABLED
                    )
                    if not eligible_families.exists():
                        messages.error(
                            request,
                            f"Cannot send network invite: {email}'s families are not accepting network invites.",
                        )
                        return redirect("family_settings", family_id=family.id)

            # Check if target family allows network invites
            policy_allowed, policy_error = _check_network_invite_policy(target_family)
            if not policy_allowed:
                messages.error(request, policy_error)
                return redirect("family_settings", family_id=family.id)

            from notifications.services.outbound_email_guard import (
                OutboundEmailCategory,
                can_send,
                get_client_ip,
                guard_error_message,
                record_send,
            )

            client_ip = get_client_ip(request)

            decision = can_send(
                user=user,
                category=OutboundEmailCategory.NETWORK_INVITE,
                recipient=email,
                ip=client_ip,
            )
            if not decision.allowed:
                messages.warning(
                    request,
                    guard_error_message(decision),
                )
                return redirect("family_settings", family_id=family.id)

            invite_code = str(uuid.uuid4())
            expires_at = timezone.now() + timedelta(days=14)

            network_name = (
                meta_family.name
                if meta_family and invitation_context == "META_JOIN"
                else meta_group_name
            )

            pending = PendingMetaFamilyMembership.objects.create(
                source_family=family,
                target_family=target_family,
                meta_family=meta_family,
                invited_email=email,
                invited_by=user,
                invite_code=invite_code,
                invitation_context=invitation_context,
                relationship_context=relationship_context or None,
                relationship_type=relationship_type or None,
                network_name=network_name,
                message=invitation_message or "",
                expires_at=expires_at,
            )

            invite_url = build_absolute_url(
                reverse(
                    "accept_network_invitation",
                    kwargs={"invite_code": pending.invite_code},
                )
            )

            from django.utils.html import escape

            network_display_name = (
                pending.meta_family.name
                if pending.meta_family
                else escape(pending.network_name or f"{family.name} Network")
            )
            safe_network_name = _sanitize_email_subject_value(network_display_name)

            email_context = {
                "inviter_name": user.get_full_name() or user.username,
                "source_family": family.name,
                "network_name": network_display_name,
                "invite_url": invite_url,
                "invitation_message": invitation_message,
                "requires_family_selection": pending.target_family is None,
            }

            html_content = render_to_string("email/network_invite.html", email_context)

            try:
                NotificationService.send_email_notification(
                    to_email=email,
                    subject=f"Connect your family to {safe_network_name} on ClanCal",
                    html_content=html_content,
                )
                record_send(
                    user=user,
                    category=OutboundEmailCategory.NETWORK_INVITE,
                    recipient=email,
                    ip=client_ip,
                )
                messages.success(
                    request,
                    f"Network invitation sent to {email}. They'll choose which family to connect.",
                )
            except Exception as exc:
                logger.error(
                    "Failed to send network invitation email to %s: %s", email, exc
                )
                messages.warning(
                    request,
                    "Network invite created, but email delivery failed. Share the link manually.",
                )

            # Queue in-app notifications to admins of eligible families.
            # Uses transaction.on_commit() to ensure the invite record is committed
            # before the Celery task runs. If notification queueing fails, the invite
            # still persists and the email was already sent.
            if existing_user:
                pending_id = str(pending.id)
                existing_user_id = str(existing_user.id)
                inviter_id = str(user.id)
                source_family_id = str(family.id)
                meta_family_id = str(meta_family.id) if meta_family else None
                network_name_for_notification = network_display_name

                def queue_notification() -> None:
                    from users.tasks import (
                        _send_network_invite_notifications,
                        send_network_invite_notifications_task,
                    )

                    try:
                        send_network_invite_notifications_task.delay(
                            pending_id=pending_id,
                            existing_user_id=existing_user_id,
                            inviter_id=inviter_id,
                            source_family_id=source_family_id,
                            meta_family_id=meta_family_id,
                            network_name=network_name_for_notification,
                        )
                    except Exception as e:
                        logger.critical(
                            "Failed to queue network invite notification task: pending=%s error=%s",
                            pending_id,
                            e,
                        )
                        # Fallback to synchronous send to avoid missing in-app notifications
                        try:
                            _send_network_invite_notifications(
                                pending=pending,
                                existing_user=existing_user,
                                inviter=user,
                                source_family=family,
                                meta_family=meta_family,
                                network_name=network_name_for_notification,
                            )
                        except Exception as exc:
                            logger.error(
                                "Fallback notification send failed for pending=%s: %s",
                                pending_id,
                                exc,
                                exc_info=True,
                            )

                transaction.on_commit(queue_notification)

            return redirect("family_settings", family_id=family.id)

        # Immediate-family invitation flow continues below
        if existing_user:
            existing_membership = FamilyMembership.objects.filter(
                user=existing_user, family=family
            ).exists()

            if existing_membership:
                messages.warning(
                    request, f"{email} is already a member of this family."
                )
                return redirect("family_settings", family_id=family.id)

        existing_invite = FamilyInvite.objects.filter(
            email=email, family=family, status="PENDING"
        ).exists()

        if existing_invite:
            messages.warning(
                request, f"There is already a pending invitation for {email}."
            )
            return redirect("family_settings", family_id=family.id)

        invite_code = str(uuid.uuid4())
        expires_at = timezone.now() + timedelta(days=7)

        invite_kwargs = {
            "family": family,
            "email": email,
            "role": role,
            "invited_by": user,
            "invite_code": invite_code,
            "expires_at": expires_at,
            "invitation_context": invitation_context,
            "create_meta_group": create_meta_group,
            "meta_group_name": meta_group_name,
            "relationship_type": relationship_type,
        }

        # Store relationship_context if this is a META family invite
        family_type = FamilyGroupType.objects.filter(family=family).first()
        if family_type and family_type.type == "META" and relationship_context:
            # Store relationship_context in the message field for META invites
            # This will be used when accepting the invitation
            if invitation_message:
                invite_kwargs["message"] = (
                    f"{invitation_message}\n[META_CONTEXT:{relationship_context}]"
                )
            else:
                invite_kwargs["message"] = f"[META_CONTEXT:{relationship_context}]"
        elif invitation_message:
            invite_kwargs["message"] = invitation_message

        # Add existing meta group if specified
        if existing_meta_group_id:
            try:
                meta_group = FamilyGroup.objects.get(id=existing_meta_group_id)
                # Verify the user is an admin of this meta group
                is_admin = FamilyMembership.objects.filter(
                    user=user, family=meta_group, is_admin=True
                ).exists()
                if is_admin:
                    invite_kwargs["existing_meta_group"] = meta_group
                else:
                    messages.warning(
                        request,
                        "You must be an admin of the network to invite others to it.",
                    )
            except FamilyGroup.DoesNotExist:
                logger.warning(
                    f"Invalid meta group ID provided: {existing_meta_group_id}"
                )

        from notifications.services.outbound_email_guard import (
            OutboundEmailCategory,
            can_send,
            get_client_ip,
            guard_error_message,
            record_send,
        )

        client_ip = get_client_ip(request)

        decision = can_send(
            user=user,
            category=OutboundEmailCategory.FAMILY_INVITE,
            recipient=email,
            ip=client_ip,
        )
        if not decision.allowed:
            messages.warning(
                request,
                guard_error_message(decision),
            )
            return redirect("family_settings", family_id=family.id)

        invite = FamilyInvite.objects.create(**invite_kwargs)

        # Generate invite URL
        invite_url = build_absolute_url(
            reverse("accept_family_invite", kwargs={"invite_code": invite_code})
        )

        # Prepare email context
        # For META family invites, use the network name instead of the immediate family name
        from django.utils.html import escape

        display_name = family.name
        if create_meta_group and meta_group_name:
            # Escape user-provided meta_group_name to prevent XSS
            display_name = escape(meta_group_name)
        elif existing_meta_group_id:
            try:
                meta_group = FamilyGroup.objects.get(id=existing_meta_group_id)
                display_name = meta_group.name
            except FamilyGroup.DoesNotExist:
                pass  # Fall back to family.name

        context = {
            "inviter_name": user.get_full_name() or user.username,
            "family_name": display_name,
            "role": role,
            "invite_url": invite_url,
            "expires_at": expires_at,
        }

        # Render email template
        html_content = render_to_string("email/family_invite.html", context)

        safe_display_name = _sanitize_email_subject_value(str(display_name))

        # Send email using existing NotificationService
        try:
            from django.db.models import F

            NotificationService.send_email_notification(
                to_email=email,
                subject=f"You're invited to join {safe_display_name} on ClanCal",
                html_content=html_content,
            )
            record_send(
                user=user,
                category=OutboundEmailCategory.FAMILY_INVITE,
                recipient=email,
                ip=client_ip,
            )
            FamilyInvite.objects.filter(id=invite.id).update(
                last_sent_at=timezone.now(),
                send_count=F("send_count") + 1,
            )
            messages.success(
                request,
                f"Invitation sent to {email}. They will receive an email with instructions to join.",
            )
        except Exception as e:
            logger.error("Failed to send invitation email: %s", str(e))
            messages.warning(
                request,
                f"Invitation created for {email}, but email delivery failed. Invite code: {invite_code}",
            )

        return redirect("family_settings", family_id=family.id)

    except FamilyGroup.DoesNotExist:
        messages.error(request, "Family not found.")
        return redirect("family_management")


@login_required
def cancel_invite(request: HttpRequest) -> HttpResponse:
    """
    Cancel an invitation and clean up any related memberships or duplicate families
    """
    if request.method != "POST":
        return redirect("family_management")

    user = cast(User, request.user)  # login_required guarantees User
    invite_id = request.POST.get("invite_id")

    if not invite_id:
        messages.error(request, "Invitation ID is required.")
        # Try to redirect back to referrer if available
        referer = request.META.get("HTTP_REFERER", "")
        if referer and url_has_allowed_host_and_scheme(
            referer,
            allowed_hosts={request.get_host()},
            require_https=request.is_secure(),
        ):
            return redirect(referer)
        return redirect("family_management")

    try:
        invite = FamilyInvite.objects.get(id=invite_id)

        # Verify the user is an admin of the family or the one who sent the invite
        has_admin_permission, _ = validate_family_admin_permission(
            user, invite.family, "cancel invitations"
        )
        is_sender = invite.invited_by == user

        if not (has_admin_permission or is_sender):
            messages.error(
                request, "You do not have permission to cancel this invitation."
            )
            return redirect("family_settings", family_id=invite.family.id)

        # Wrap all database operations in a transaction for consistency
        with transaction.atomic():
            # Check if the invited user exists and has memberships to clean up
            invited_user = (
                User.objects.select_related("profile")
                .filter(email=invite.email)
                .first()
            )

            if invited_user:
                # Get the family type
                family_type = FamilyGroupType.objects.filter(
                    family=invite.family
                ).first()

                if family_type and family_type.type == "META":
                    # For META family invites, remove the connection between user's family and the META network
                    profile = getattr(invited_user, "profile", None)
                    if profile and profile.primary_family:
                        # Remove MetaFamilyMembership if it exists
                        deleted_count, _ = MetaFamilyMembership.objects.filter(
                            family=profile.primary_family,
                            meta_family=invite.family,
                        ).delete()
                        if deleted_count > 0:
                            logger.info(
                                f"Removed {profile.primary_family.name} from META network {invite.family.name} during invite cancellation"
                            )

                    # Also remove direct membership if user was incorrectly added as a direct member
                    FamilyMembership.objects.filter(
                        user=invited_user, family=invite.family
                    ).delete()

                else:
                    # For IMMEDIATE family invites, remove direct membership
                    deleted_count, _ = FamilyMembership.objects.filter(
                        user=invited_user, family=invite.family
                    ).delete()

                    if deleted_count > 0:
                        logger.info(
                            f"Removed user {invited_user.id} from family {invite.family.name} during invite cancellation"
                        )

                        # If this was the user's primary family and they have no other families, clear it
                        profile = getattr(invited_user, "profile", None)
                        if profile and profile.primary_family_id == invite.family_id:
                            # Check if user has any other family memberships
                            other_membership = (
                                FamilyMembership.objects.filter(user=invited_user)
                                .exclude(family=invite.family)
                                .select_related("family")
                                .first()
                            )

                            if other_membership:
                                # Set another family as primary
                                profile.primary_family = other_membership.family
                            else:
                                # User has no other families
                                profile.primary_family = None
                            profile.save(update_fields=["primary_family"])

            # Cancel the invitation (use CANCELLED instead of DECLINED for clarity)
            invite.status = "CANCELLED"
            invite.save(update_fields=["status"])

        messages.success(
            request,
            f"Invitation to {invite.email} has been cancelled and any related memberships have been removed.",
        )
        return redirect("family_settings", family_id=invite.family.id)

    except FamilyInvite.DoesNotExist:
        messages.error(request, "Invitation not found.")
        return redirect("family_management")


@login_required
def resend_invite(request: HttpRequest) -> HttpResponse:
    """
    Resend an invitation email
    """
    if request.method != "POST":
        return redirect("family_management")

    user = cast(User, request.user)  # login_required guarantees User
    invite_id = request.POST.get("invite_id")

    if not invite_id:
        messages.error(request, "Invitation ID is required.")
        return redirect("family_management")

    try:
        invite = FamilyInvite.objects.get(id=invite_id)

        from notifications.services.outbound_email_guard import (
            OutboundEmailCategory,
            can_send,
            get_client_ip,
            get_cooldown_seconds,
            guard_error_message,
            record_send,
        )

        cooldown_seconds = get_cooldown_seconds(
            category=OutboundEmailCategory.FAMILY_INVITE
        )
        if invite.last_sent_at and cooldown_seconds > 0:
            if (
                timezone.now() - invite.last_sent_at
            ).total_seconds() < cooldown_seconds:
                messages.warning(
                    request,
                    "Please wait a few minutes before resending this invitation again.",
                )
                return redirect("family_management")

        # Verify the user is an admin of the family or the one who sent the invite
        has_admin_permission, _ = validate_family_admin_permission(
            user, invite.family, "resend invitations"
        )
        is_sender = invite.invited_by == user

        if not (has_admin_permission or is_sender):
            messages.error(
                request, "You do not have permission to resend this invitation."
            )
            return redirect("family_management")

        # Only resend pending or cancelled invitations
        if invite.status not in ["PENDING", "CANCELLED"]:
            messages.error(
                request, "Only pending or cancelled invitations can be resent."
            )
            return redirect("family_management")

        # Check if user already exists and has existing memberships
        existing_user = User.objects.filter(email=invite.email).first()

        if existing_user:
            # Get the family type
            family_type = FamilyGroupType.objects.filter(family=invite.family).first()

            if family_type and family_type.type == "IMMEDIATE":
                # Check for existing membership in immediate family
                if FamilyMembership.objects.filter(
                    user=existing_user, family=invite.family
                ).exists():
                    messages.warning(
                        request,
                        f"{invite.email} is already a member of {invite.family.name}. No need to resend invitation.",
                    )
                    return redirect("family_settings", family_id=invite.family.id)

            elif family_type and family_type.type == "META":
                # Check if user's family is already connected to META network
                if (
                    hasattr(existing_user, "profile")
                    and existing_user.profile.primary_family
                ):
                    if MetaFamilyMembership.objects.filter(
                        family=existing_user.profile.primary_family,
                        meta_family=invite.family,
                    ).exists():
                        messages.warning(
                            request,
                            f"{invite.email}'s family is already connected to the {invite.family.name} network. No need to resend invitation.",
                        )
                        return redirect("family_settings", family_id=invite.family.id)

        # Reset status to PENDING if it was cancelled
        if invite.status == "CANCELLED":
            with transaction.atomic():
                # Refresh the invite to ensure we have the latest state
                invite.refresh_from_db(fields=["status"])
                if invite.status == "CANCELLED":
                    invite.status = "PENDING"
                    invite.save(update_fields=["status"])

        # Check if invitation has expired and optionally extend it
        # Handle None or invalid expires_at
        if not invite.expires_at:
            invite.expires_at = timezone.now() + timedelta(days=7)
            invite.save()
            logger.info(f"Set expiration for invite {invite.id}")
        else:
            # Ensure we have a timezone-aware datetime for comparison
            exp_date = invite.expires_at
            if timezone.is_naive(exp_date):
                exp_date = timezone.make_aware(exp_date)

            if exp_date < timezone.now():
                invite.expires_at = timezone.now() + timedelta(days=7)
                invite.save()
                logger.info(f"Extended expiration for invite {invite.id}")

        # Generate invite URL
        invite_url = build_absolute_url(
            reverse("accept_family_invite", kwargs={"invite_code": invite.invite_code})
        )

        # Prepare email context
        display_name = invite.family.name
        if invite.meta_group_name:
            display_name = invite.meta_group_name
        elif invite.existing_meta_group:
            display_name = invite.existing_meta_group.name

        context = {
            "inviter_name": invite.invited_by.get_full_name()
            or invite.invited_by.username,
            "family_name": display_name,
            "role": invite.role,
            "invite_url": invite_url,
            "expires_at": invite.expires_at,
        }

        # Render email template
        html_content = render_to_string("email/family_invite.html", context)

        client_ip = get_client_ip(request)

        decision = can_send(
            user=user,
            category=OutboundEmailCategory.FAMILY_INVITE,
            recipient=invite.email,
            ip=client_ip,
        )
        if not decision.allowed:
            messages.warning(
                request,
                guard_error_message(decision),
            )
            return redirect("family_management")

        # Send email using existing NotificationService
        try:
            from django.db.models import F

            NotificationService.send_email_notification(
                to_email=invite.email,
                subject=f"Reminder: You're invited to join {display_name} on ClanCal",
                html_content=html_content,
            )
            record_send(
                user=user,
                category=OutboundEmailCategory.FAMILY_INVITE,
                recipient=invite.email,
                ip=client_ip,
            )
            FamilyInvite.objects.filter(id=invite.id).update(
                last_sent_at=timezone.now(),
                send_count=F("send_count") + 1,
            )
            messages.success(
                request,
                f"Invitation resent to {invite.email}. They will receive an email reminder.",
            )
        except Exception as e:
            logger.error(
                f"Failed to resend invitation email for invite {invite.id}: {str(e)}"
            )
            messages.warning(
                request,
                f"Failed to resend email to {invite.email}. Please try again later.",
            )

