@login_required
def accept_invite(request: HttpRequest) -> HttpResponse:
    """
    Accept an invitation
    """
    if request.method != "POST":
        return redirect("family_management")

    user = cast(User, request.user)  # login_required guarantees User
    invite_id = request.POST.get("invite_id")

    # Get network creation preferences from the invitation (stored during creation)
    # These override any form data since they were specified when the invite was sent

    if not invite_id:
        messages.error(request, "Invitation ID is required.")
        return redirect("family_management")

    try:
        invite = FamilyInvite.objects.get(id=invite_id)

        # Verify the invitation is for this user
        if invite.email != user.email:
            messages.error(request, "This invitation is not for your account.")
            return redirect("family_management")

        # Check if invite is still valid
        if invite.status != "PENDING":
            messages.error(request, "This invitation is no longer valid.")
            return redirect("family_management")

        if invite.expires_at < timezone.now():
            invite.status = "EXPIRED"
            invite.save()
            messages.error(request, "This invitation has expired.")
            return redirect("family_management")

        # Use atomic transaction to prevent race conditions
        try:
            with transaction.atomic():
                # Check if user is already a member of this family
                existing_membership = FamilyMembership.objects.filter(
                    user=user, family=invite.family
                ).exists()

                if existing_membership:
                    messages.warning(
                        request, f"You are already a member of {invite.family.name}."
                    )
                    invite.status = "ACCEPTED"
                    invite.save()
                    return redirect("family_management")

                # Create the family membership
                FamilyMembership.objects.create(
                    user=user,
                    family=invite.family,
                    role=invite.role,
                    is_admin=False,  # New members are not admins by default
                )

                # Update the invite status
                invite.status = "ACCEPTED"
                invite.save()

                # If this is the user's first family, set it as primary
                if not user.profile.primary_family:
                    success, error_msg = assign_primary_family(
                        user, invite.family, transaction_safe=False
                    )
                    if not success:
                        logger.error(
                            f"Failed to assign primary family during invite acceptance: {error_msg}"
                        )
                        # Continue anyway - this is not a critical failure

                # Handle family relationships if specified in the invitation
                if invite.relationship_type and user.profile.primary_family:
                    # Create relationship between the two families using centralized utility
                    created_count, error_msg = create_family_relationship(
                        user.profile.primary_family,
                        invite.family,
                        invite.relationship_type,
                        transaction_safe=False,
                    )

                    if error_msg:
                        logger.warning(
                            f"Failed to create family relationship during invite acceptance: {error_msg}"
                        )
                        # Continue anyway - relationship creation is optional

                    # Create meta group if requested in the invitation - with proper authorization validation
                    if invite.create_meta_group and invite.meta_group_name:
                        # Validate that user has permission to create meta groups
                        # Only allow if user is admin of their primary family
                        if not user.profile.primary_family:
                            logger.warning(
                                f"User {user.username} attempted to create meta group without primary family"
