                            )
                        else:
                            has_permission, error_msg = (
                                validate_family_admin_permission(
                                    user,
                                    user.profile.primary_family,
                                    "create meta groups",
                                )
                            )

                            if not has_permission:
                                logger.warning(
                                    f"User {user.username} attempted to create meta group without admin permission: {error_msg}"
                                )
                                messages.warning(
                                    request,
                                    "You must be an admin of your family to create a network.",
                                )
                            else:
                                # Validate both families can be part of meta group
                                # Note: meta_family is None here as we're checking eligibility before creation
                                is_valid1, error1 = validate_meta_family_membership(
                                    user.profile.primary_family,
                                    None,
                                )
                                is_valid2, error2 = validate_meta_family_membership(
                                    invite.family,
                                    None,
                                )

                                if not (is_valid1 and is_valid2):
                                    logger.error(
                                        f"Meta family validation failed: {error1 or error2}"
                                    )
                                    messages.error(
                                        request,
                                        "Unable to create network due to validation errors.",
                                    )
                                else:
                                    # Create the meta family group
                                    meta_family = FamilyGroup.objects.create(
                                        name=invite.meta_group_name
                                    )

                                    # Set the group type to META
                                    FamilyGroupType.objects.update_or_create(
                                        family=meta_family,
                                        defaults={"type": "META"},
                                    )

                                    # Note: Users are NOT direct members of META families.
                                    # Only families can be members of META families.
                                    # The user maintains their role in their immediate family.

                                    # Add both families as members of the meta group with validation
                                    MetaFamilyMembership.objects.create(
                                        family=user.profile.primary_family,
                                        meta_family=meta_family,
                                    )

                                    MetaFamilyMembership.objects.create(
                                        family=invite.family, meta_family=meta_family
                                    )

                                    logger.info(
                                        f"User {user.username} created meta group '{invite.meta_group_name}' with families {user.profile.primary_family.name} and {invite.family.name}"
                                    )
                                    messages.success(
                                        request,
                                        f"Network '{invite.meta_group_name}' has been created successfully.",
                                    )

        except Exception as e:
            logger.error(f"Error during invite acceptance: {str(e)}")
            messages.error(
                request,
                "An error occurred while accepting the invitation. Please try again.",
            )
            return redirect("family_management")

        messages.success(
            request,
            f"You have joined {invite.family.name} as a {invite.get_role_display()}.",
        )
        return redirect("family_management")

    except FamilyInvite.DoesNotExist:
        messages.error(request, "Invitation not found.")
        return redirect("family_management")


