    """
    Confirm and process family invite acceptance for authenticated users
    """
    user = cast(User, request.user)  # login_required guarantees User
    try:
        # Use atomic transaction to prevent race conditions
        with transaction.atomic():
            # Use select_for_update to prevent race conditions
            invite = FamilyInvite.objects.select_for_update().get(
                invite_code=invite_code
            )

            # Verify the invitation is for this user
            if invite.email.lower() != user.email.lower():
                messages.error(request, "This invitation is not for your account.")
                return redirect("family_management")

            # Validate invitation based on its context
            if invite.invitation_context == "IMMEDIATE":
                is_valid, error_msg = validate_immediate_family_invitation(invite, user)
            else:
                is_valid, error_msg = validate_meta_family_invitation(invite, user)

            if not is_valid:
                if error_msg and "expired" in error_msg.lower():
                    invite.status = "EXPIRED"
                    invite.save()
                messages.error(request, error_msg or "Validation failed")
                return redirect("family_management")

            # Process based on invitation context
            if invite.invitation_context == "META_JOIN":
                # Handle adding to existing meta group
                meta_group = invite.existing_meta_group

                # User should already have a primary family
                if not user.profile.primary_family:
                    messages.error(
                        request,
                        "You must have a primary family before joining a family network.",
                    )
                    return redirect("family_management")

                # Check if the user's family is already in this meta group
                existing_membership = MetaFamilyMembership.objects.filter(
                    family=user.profile.primary_family,
                    meta_family=meta_group,
                ).exists()

                if not existing_membership:
                    primary_family = user.profile.primary_family
                    if not primary_family:
                        messages.error(
                            request, "You must have a primary family to join a network."
                        )
                        return redirect("family_management")

                    # Add user's family to the existing meta group
                    # meta_group is guaranteed to be a FamilyGroup at this point
                    MetaFamilyMembership.objects.create(
                        family=primary_family,
                        meta_family=meta_group,  # type: ignore[misc]
                    )

                    # Handle family relationships if specified
                    if invite.relationship_type:
                        created_count, error_msg = create_family_relationship(
                            user.profile.primary_family,
                            invite.family,
                            invite.relationship_type,
                            transaction_safe=False,
                        )

                        if error_msg:
                            logger.warning(
                                f"Failed to create family relationship during invite acceptance: {error_msg}"
                            )

                    meta_group_name = meta_group.name if meta_group else "Unknown"
                    primary_family_name = (
                        user.profile.primary_family.name
                        if user.profile.primary_family
                        else "Unknown"
                    )
                    logger.info(
                        f"User {user.username} added their family {primary_family_name} to meta group '{meta_group_name}'"
                    )
                    messages.success(
                        request,
                        f"Your family has been added to the '{meta_group_name}' network.",
                    )
                else:
                    meta_group_name = meta_group.name if meta_group else "Unknown"
                    messages.info(
                        request,
                        f"Your family is already part of the '{meta_group_name}' network.",
                    )

            # Check if this invitation is for creating a new network connection
            elif invite.invitation_context == "META_CREATE":
                # Handle network creation invitation
                # User should already have a primary family if they're being invited to create a network
                if not user.profile.primary_family:
                    messages.error(
                        request,
                        "You must have a primary family before joining a family network.",
                    )
                    return redirect("family_management")

                # Validate that user has permission to create meta groups
                has_permission, error_msg = validate_family_admin_permission(
                    user,
                    user.profile.primary_family,
                    "create meta groups",
                )

                if not has_permission:
                    messages.error(
                        request,
                        "You must be an admin of your family to create a network.",
                    )
                    return redirect("family_management")

                # Validate both families can be part of meta group
                # Note: meta_family is None here as we're checking eligibility before creation
                is_valid1, error1 = validate_meta_family_membership(
                    user.profile.primary_family,
                    None,  # type: ignore[arg-type]
                )
                is_valid2, error2 = validate_meta_family_membership(
                    invite.family,
                    None,  # type: ignore[arg-type]
                )

                if not (is_valid1 and is_valid2):
