                    messages.error(
                        request,
                        "Unable to create network due to validation errors.",
                    )
                    return redirect("family_management")

                # Create the meta family group
                network_name = invite.meta_group_name or "Family Network"
                meta_family = FamilyGroup.objects.create(name=network_name)

