                        # Join directly
                        FamilyMembership.objects.create(
                            user=user,
                            family=invite.family,
                            role=invite.role,
                            is_admin=False,
                        )

                        # If this is the user's first family, set it as primary
                        if not user.profile.primary_family:
                            user.profile.primary_family = invite.family
                            user.profile.save()

                        messages.success(
                            request,
                            f"Welcome! You've joined {invite.family.name} as a {invite.get_role_display()}.",
                        )

            # Mark invite as accepted
            invite.status = "ACCEPTED"
            invite.save()

            # Clear session
            if "family_invite_code" in request.session:
                del request.session["family_invite_code"]

            return redirect("family_management")

    except FamilyInvite.DoesNotExist:
        messages.error(request, "Invitation not found.")
        return redirect("family_management")
    except Exception as e:
        logger.error(f"Error accepting family invite: {str(e)}")
        messages.error(
            request,
            "An error occurred while accepting the invitation. Please try again.",
        )
        return redirect("family_management")
