@login_required
def create_network_with_invites(request: HttpRequest) -> HttpResponse:
    """
    Create a family network immediately and send pending invitations to families.
    This allows the network to exist and be shared before families accept.
    """
    if request.method != "POST":
        return redirect("family_management")

    user = cast(User, request.user)

    # Get form data
    network_name = request.POST.get("network_name")
    from_family_id = request.POST.get("from_family_id")
    invited_family_emails = request.POST.getlist("invited_families[]")
    relationship_contexts = request.POST.getlist("relationship_contexts[]")
    auto_join_creator = request.POST.get("auto_join_creator") == "1"
    invitation_message = request.POST.get("invitation_message", "")
    creator_relationship_context = (
        request.POST.get("creator_relationship_context") or ""
    ).strip()

    if not network_name:
        messages.error(request, "Network name is required.")
        return redirect("family_management")

    if creator_relationship_context and (
        creator_relationship_context not in _VALID_RELATIONSHIP_CONTEXTS
    ):
        messages.error(request, "Invalid relationship context provided.")
        return redirect("family_management")

    for context_value in relationship_contexts:
        context_value = (context_value or "").strip()
        if context_value and context_value not in _VALID_RELATIONSHIP_CONTEXTS:
            messages.error(request, "Invalid relationship context provided.")
            return redirect("family_management")

    # Verify user has permission to create network from this family
    if from_family_id:
        try:
            from_family = FamilyGroup.objects.get(id=from_family_id)
            has_permission, error_msg = validate_family_admin_permission(
                user, from_family, "create family networks"
            )

            if not has_permission:
                messages.error(request, error_msg or "Permission denied")
                return redirect("family_management")
        except FamilyGroup.DoesNotExist:
            messages.error(request, "Invalid family specified.")
            return redirect("family_management")
    else:
        from_family = None

    try:
        with transaction.atomic():
            # Create the network immediately
            network = FamilyGroup.objects.create(name=network_name)
            FamilyGroupType.objects.update_or_create(
                family=network, defaults={"type": "META"}
            )

            # Add the creator as an admin of the network
            FamilyMembership.objects.create(
                user=user,
                family=network,
                role="PARENT",
                is_admin=True,
            )

            # Auto-join creator's family if requested
            if auto_join_creator and from_family:
                MetaFamilyMembership.objects.create(
                    family=from_family,
                    meta_family=network,
                    relationship_context=creator_relationship_context or None,
                )

            # Create pending memberships for invited families
            expires_at = timezone.now() + timedelta(days=30)  # 30-day expiration
            pending_memberships = []
            skipped_families = []

            # Batch lookup users by email to reduce N+1 queries
            valid_emails = [e for e in invited_family_emails if e]
            invited_users = list(UserModel.objects.filter(email__in=valid_emails))
            user_by_email = {u.email.lower(): u for u in invited_users}

            # Bulk prefetch admin family memberships for all invited users
            # This avoids N+1 queries when iterating over users
            admin_memberships = (
                FamilyMembership.objects.filter(user__in=invited_users, is_admin=True)
                .exclude(family__group_type__type="META")
                .exclude(family_id=network.id)
                .select_related("family")
            )

            # Build mapping: user_id -> list of admin families
            user_admin_families: dict[int, list[FamilyGroup]] = {}
            all_admin_family_ids: set[UUID] = set()
            for membership in admin_memberships:
                user_admin_families.setdefault(membership.user_id, []).append(
                    membership.family
                )
                all_admin_family_ids.add(membership.family_id)

            # Bulk prefetch existing and pending memberships to avoid N+1 in inner loop
            existing_membership_families = set(
                MetaFamilyMembership.objects.filter(
                    family_id__in=all_admin_family_ids, meta_family=network
                ).values_list("family_id", flat=True)
            )

            pending_membership_families = set(
                PendingMetaFamilyMembership.objects.filter(
                    target_family_id__in=all_admin_family_ids,
                    meta_family=network,
                    status="PENDING",
                ).values_list("target_family_id", flat=True)
            )

            for i, email in enumerate(invited_family_emails):
                if not email:
                    continue

                invited_user = user_by_email.get(email.lower())
                if not invited_user:
                    logger.info(
                        f"No user found with email {email} for network invitation"
                    )
                    continue

                # Get admin families from prefetched data (O(1) lookup)
                admin_families = user_admin_families.get(invited_user.id, [])

                for family in admin_families:
                    # Check policy first (cheapest check - fail fast)
                    policy_allowed, _ = _check_network_invite_policy(family)
                    if not policy_allowed:
                        skipped_families.append(family.name)
                        continue

                    # Check if already has active membership (O(1) set lookup)
                    if family.id in existing_membership_families:
                        continue

                    # Check if already has pending membership (O(1) set lookup)
                    if family.id in pending_membership_families:
                        continue

                    # Create pending membership
                    invite_code = str(uuid.uuid4())
                    relationship_context = (
                        relationship_contexts[i]
                        if i < len(relationship_contexts)
                        else None
                    )
                    if relationship_context:
                        relationship_context = relationship_context.strip()
                        if relationship_context not in _VALID_RELATIONSHIP_CONTEXTS:
                            relationship_context = None

                    pending = PendingMetaFamilyMembership.objects.create(
                        source_family=network,
                        target_family=family,
                        meta_family=network,
                        invited_email=invited_user.email,
                        invited_by=user,
                        invite_code=invite_code,
                        invitation_context="META_JOIN",
                        status="PENDING",
                        relationship_context=relationship_context,
                        message=invitation_message,
                        expires_at=expires_at,
                    )
                    pending_memberships.append(pending)

        # Queue notifications after transaction commits successfully
        def queue_notifications() -> None:
            from users.tasks import send_network_invite_notifications_task

            for pending in pending_memberships:
                # Get the invited user for this pending membership
                invited_user = user_by_email.get((pending.invited_email or "").lower())
                if invited_user:
                    try:
                        send_network_invite_notifications_task.delay(
                            pending_id=str(pending.id),
                            existing_user_id=str(invited_user.id),
                            inviter_id=str(user.id),
                            source_family_id=str(network.id),
                            meta_family_id=str(network.id),
                            network_name=network_name,
                        )
                    except Exception as e:
                        logger.error(
                            "Failed to queue notification for pending=%s: %s",
                            pending.id,
                            e,
                        )

        transaction.on_commit(queue_notifications)

        # Success message
        message = f'Network "{network_name}" created successfully.'
        if auto_join_creator and from_family:
            message += f" {from_family.name} has been added to the network."
        if pending_memberships:
            message += f" {len(pending_memberships)} invitation(s) sent to families."

        messages.success(request, message)

        # Notify user about any families that were skipped due to policy
        if skipped_families:
            # Deduplicate family names (same family could appear multiple times)
            unique_skipped = sorted(set(skipped_families))
            messages.info(
                request,
                f"Some families were skipped as they don't accept network invites: "
                f"{', '.join(unique_skipped)}",
            )

        # Redirect to network settings page
        return redirect("family_settings", family_id=network.id)

    except Exception as e:
        logger.error(f"Error creating network: {str(e)}")
        messages.error(request, "An error occurred while creating the network.")
        return redirect("family_management")


@login_required
def invite_family_to_network(request: HttpRequest, network_id: str) -> HttpResponse:
    """
    Invite a family to join an existing network.
    Creates a pending membership that the family can accept.
    """
    if request.method != "POST":
        return redirect("family_settings", family_id=network_id)

    user = cast(User, request.user)

    try:
        network = FamilyGroup.objects.get(id=network_id)

        # Verify this is a META family
        if not FamilyGroupType.objects.filter(family=network, type="META").exists():
            messages.error(request, "This is not a family network.")
            return redirect("family_settings", family_id=network_id)

        # Verify user is an admin of the network
        is_admin = FamilyMembership.objects.filter(
            user=user, family=network, is_admin=True
        ).exists()

        if not is_admin:
            messages.error(request, "You must be a network admin to invite families.")
            return redirect("family_settings", family_id=network_id)

        # Get form data
        family_id = request.POST.get("family_id")
        email = request.POST.get("email")
        relationship_context = (request.POST.get("relationship_context") or "").strip()
        message = request.POST.get("message", "")

        if relationship_context and (
            relationship_context not in _VALID_RELATIONSHIP_CONTEXTS
        ):
            messages.error(request, "Invalid relationship context provided.")
            return redirect("family_settings", family_id=network_id)

        # Find the family to invite
        invited_family = None

        if family_id:
            # Direct family ID provided
            try:
                invited_family = FamilyGroup.objects.get(id=family_id)
            except FamilyGroup.DoesNotExist:
                messages.error(request, "Family not found.")
                return redirect("family_settings", family_id=network_id)

        elif email:
            # Try to find family by admin email
            try:
                invited_user = UserModel.objects.get(email=email)
            except User.DoesNotExist:
                invited_user = None

            if invited_user:
                admin_families = (
                    FamilyGroup.objects.filter(
                        memberships__user=invited_user, memberships__is_admin=True
                    )
                    .exclude(id=network.id)
                    .exclude(group_type__type="META")
                )

                primary_family = getattr(invited_user.profile, "primary_family", None)
                if (
                    primary_family
                    and admin_families.filter(id=primary_family.id).exists()
                ):
                    invited_family = primary_family
                elif admin_families.count() == 1:
                    invited_family = admin_families.first()

        # Check if already a member
        if (
            invited_family
            and MetaFamilyMembership.objects.filter(
                family=invited_family, meta_family=network
            ).exists()
        ):
            messages.warning(
                request, f"{invited_family.name} is already a member of this network."
            )
            return redirect("family_settings", family_id=network_id)

        # Check for existing pending invitation
        existing_pending = None
        if invited_family:
            existing_pending = PendingMetaFamilyMembership.objects.filter(
                target_family=invited_family,
                meta_family=network,
                status="PENDING",
            ).first()

            if existing_pending:
                messages.warning(
                    request,
                    f"There is already a pending invitation for {invited_family.name}.",
                )
                return redirect("family_settings", family_id=network_id)

        # Check if target family allows network invites
        policy_allowed, policy_error = _check_network_invite_policy(invited_family)
        if not policy_allowed:
            messages.error(request, policy_error)
            return redirect("family_settings", family_id=network_id)

        # Create pending membership
        invite_code = str(uuid.uuid4())
        expires_at = timezone.now() + timedelta(days=30)

        pending = PendingMetaFamilyMembership.objects.create(
            source_family=network,
            target_family=invited_family,
            meta_family=network,
            invited_email=email,
            invited_by=user,
            invite_code=invite_code,
            invitation_context="META_JOIN",
            status="PENDING",
            relationship_context=relationship_context or None,
            message=message,
            expires_at=expires_at,
        )

        # Queue notification after the pending membership is committed
        invited_user = UserModel.objects.filter(email=email).first() if email else None
        if invited_user:
            # Capture values for closure
            pending_id = str(pending.id)
            invited_user_id = str(invited_user.id)
            inviter_id = str(user.id)
            network_id_str = str(network.id)
            network_name_str = network.name

            def queue_notification() -> None:
                from users.tasks import send_network_invite_notifications_task

                try:
                    send_network_invite_notifications_task.delay(
                        pending_id=pending_id,
                        existing_user_id=invited_user_id,
                        inviter_id=inviter_id,
                        source_family_id=network_id_str,
                        meta_family_id=network_id_str,
                        network_name=network_name_str,
                    )
                except Exception as e:
                    logger.error(
                        "Failed to queue notification for pending=%s: %s",
                        pending_id,
                        e,
                    )

            transaction.on_commit(queue_notification)

        target_label = invited_family.name if invited_family else email
        messages.success(
            request, f"Invitation sent to {target_label} to join the network."
        )

        return redirect("family_settings", family_id=network_id)

    except FamilyGroup.DoesNotExist:
        messages.error(request, "Network not found.")
        return redirect("family_management")


@login_required
def accept_network_invitation(request: HttpRequest, invite_code: str) -> HttpResponse:
    """Accept a pending network membership invitation."""
    logger.info(
        "Network invitation accessed: invite_code=%s, user=%s, ip=%s",
        invite_code,
        request.user.id if request.user.is_authenticated else "anonymous",
        request.META.get("REMOTE_ADDR", "unknown"),
    )

    pending = get_object_or_404(
        PendingMetaFamilyMembership, invite_code=invite_code, status="PENDING"
    )

    if pending.is_expired():
        pending.status = "EXPIRED"
        pending.save(update_fields=["status"])
        logger.warning(
            "Expired network invitation accessed: invite_code=%s, user=%s",
            invite_code,
            request.user.id,
        )
        messages.error(request, "This invitation has expired.")
        return redirect("family_management")

    user = cast(User, request.user)

    if not user.is_authenticated:
        login_url = reverse("account_login")
        return redirect(f"{login_url}?next={request.get_full_path()}")

    invited_email = (pending.invited_email or "").strip()
    user_email = (user.email or "").strip()
    if not pending.target_family and invited_email:
        if user_email.lower() != invited_email.lower():
            logger.warning(
                "Invitation email mismatch: invite_code=%s, invited_email=%s, user=%s",
                invite_code,
                invited_email,
                user.id,
            )
            messages.error(
                request,
                "This invitation was sent to a different email address.",
            )
            return redirect("family_management")

    selectable_families = get_user_admin_families(user)
    selectable_families = selectable_families.exclude(group_type__type="META")
    selectable_families = selectable_families.exclude(
        network_invite_policy=FamilyGroup.NetworkInvitePolicy.DISABLED
    )
    if pending.meta_family_id:
        selectable_families = selectable_families.exclude(id=pending.meta_family_id)

    target_family = pending.target_family
    if target_family and not selectable_families.filter(id=target_family.id).exists():
        logger.info(
            "Clearing invalid preselected family for network invite: invite_code=%s, target_family=%s, network=%s",
            invite_code,
            target_family.id,
            pending.meta_family_id,
        )
        pending.target_family = None
        pending.save(update_fields=["target_family"])
        target_family = None
        messages.info(
            request,
            "Please choose which family should join this network before accepting.",
        )

    if target_family:
        has_permission, error_msg = validate_family_admin_permission(
            user, target_family, "accept network invitations"
        )
        if not has_permission:
            logger.warning(
                "Unauthorized network invite access: invite_code=%s, user=%s, family=%s",
                invite_code,
                user.id,
                target_family.id,
            )
            messages.error(request, error_msg or "Permission denied")
            return redirect("family_management")
    else:
        if not selectable_families.exists():
            messages.error(
                request,
                "You need to be an admin of at least one family before accepting this invitation.",
            )
            return redirect("family_management")

    if request.method == "POST":
        action = request.POST.get("action")

        if action == "accept":
            raw_family_id = (
                str(target_family.id)
                if target_family
                else request.POST.get("family_id")
            )

            if raw_family_id is None:
                messages.error(
                    request, "Please choose which family should join the network."
                )
            else:
                family_id = str(raw_family_id).strip()
                if not family_id:
                    messages.error(
                        request, "Please choose which family should join the network."
                    )
                else:
                    try:
                        selected_family = FamilyGroup.objects.get(id=family_id)
                    except FamilyGroup.DoesNotExist:
                        messages.error(request, "Selected family could not be found.")
                    else:
                        if (
                            pending.meta_family_id
                            and selected_family.id == pending.meta_family_id
                        ):
                            messages.error(
                                request,
                                "A network cannot be connected to itself. Please pick a family.",
                            )
                        elif FamilyGroupType.objects.filter(
                            family=selected_family, type="META"
                        ).exists():
                            messages.error(
                                request,
                                "Please choose an immediate family to join this network.",
                            )
                        else:
                            if (
                                selected_family.network_invite_policy
                                == FamilyGroup.NetworkInvitePolicy.DISABLED
                            ):
                                messages.error(
                                    request,
                                    f"{selected_family.name} is not accepting network invites.",
                                )
                            else:
                                has_permission, error_msg = (
                                    validate_family_admin_permission(
                                        user,
                                        selected_family,
                                        "accept network invitations",
                                    )
                                )

                                if not has_permission:
                                    messages.error(
                                        request, error_msg or "Permission denied"
                                    )
                                else:
                                    relationship_context = (
                                        request.POST.get("relationship_context") or None
                                    )
                                    membership = pending.accept(
                                        accepting_user=user,
                                        selected_family=selected_family,
                                        relationship_context=relationship_context,
                                    )

                                    if membership:
                                        network_name = (
                                            pending.meta_family.name
                                            if pending.meta_family
                                            else pending.network_name
                                            or "family network"
                                        )
                                        logger.info(
                                            "Network invitation accepted: invite_code=%s, family=%s, network=%s, user=%s",
                                            invite_code,
                                            selected_family.id,
                                            pending.meta_family_id,
                                            user.id,
                                        )
                                        messages.success(
                                            request,
                                            f"{selected_family.name} has joined the {network_name} network!",
                                        )
                                        return redirect(
                                            "family_settings",
                                            family_id=selected_family.id,
                                        )
                                    else:
                                        messages.error(
                                            request,
                                            "We couldn't process this invitation. Please try again.",
                                        )

        elif action == "decline":
            if pending.decline(declining_user=user):  # type: ignore[no-untyped-call]
                logger.info(
                    "Network invitation declined: invite_code=%s, user=%s",
                    invite_code,
                    user.id,
                )
                messages.info(request, "Invitation declined.")
            else:
                messages.error(request, "Could not decline this invitation.")
            return redirect("family_management")

    context = {
        "pending": pending,
        "network": pending.meta_family,
        "invited_by": pending.invited_by,
        "selectable_families": selectable_families,
        "require_family_selection": pending.target_family is None,
    }

    return render(request, "users/accept_network_invitation.html", context)


@login_required
def cancel_network_invite(request: HttpRequest, family_id: str) -> HttpResponse:
    """
    Cancel a pending network invitation.
    Can be called from either the network side or the invited family side.
    """
    if request.method != "POST":
        return redirect("family_settings", family_id=family_id)

    user = cast(User, request.user)
    invite_id = request.POST.get("invite_id")

    if not invite_id or not invite_id.isdigit():
        messages.error(request, "Invitation ID is required.")
        return redirect("family_settings", family_id=family_id)

    try:
        pending = PendingMetaFamilyMembership.objects.get(
            id=invite_id, status="PENDING"
        )

        # Check permissions - either network admin or invited family admin can cancel
        if pending.meta_family:
            is_network_admin = FamilyMembership.objects.filter(
                user=user, family=pending.meta_family, is_admin=True
            ).exists()
        else:
            is_network_admin = FamilyMembership.objects.filter(
                user=user, family=pending.source_family, is_admin=True
            ).exists()

        is_family_admin = False
        if pending.target_family:
            is_family_admin = FamilyMembership.objects.filter(
                user=user, family=pending.target_family, is_admin=True
            ).exists()

        if not (is_network_admin or is_family_admin):
            messages.error(
                request, "You don't have permission to cancel this invitation."
            )
            return redirect("family_settings", family_id=family_id)

        # Cancel the invitation
        pending.status = "EXPIRED"
        pending.save(update_fields=["status"])

        messages.success(request, "Network invitation has been cancelled.")
        return redirect("family_settings", family_id=family_id)

    except PendingMetaFamilyMembership.DoesNotExist:
        messages.error(request, "Invitation not found.")
        return redirect("family_settings", family_id=family_id)


